// Generated by npm run build:web. API responses and credentials are never cached.
const CACHE="atelier-stock-a36156499f64";
const ASSETS=["/","/stock.js","/navigation.js","/stock-charts.js","/stock-i18n.js","/install.js","/theme.css","/manifest.webmanifest","/icons/stock-192.png","/icons/stock-512.png","/icons/stock-maskable-512.png"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('atelier-stock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);
 if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/catalog/')||!ASSETS.includes(url.pathname))return;
 event.respondWith(fetch(event.request).catch(()=>caches.open(CACHE).then(cache=>cache.match(url.pathname))));
});
